mapper.select:
/*selectMasterMdCmPromotionMarketCatalogList*/ SELECT A.ITEM_NO ITEM_NO , A.DESCRIPTION DESCRIPTION , A.MAKER_NAME AS MAKER_NAME , A.ADD_DATE AS ADD_DATE , DECODE (A.STATUS, 'S', '요청', 'C', '게시', 'B', '반려', 'R', '게시', 'A', '보관', 'D', '삭제', 'V', '추천') AS STATUS , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT) AS AGENT_NAME , A.SPECIFICATION AS SPECIFICATION , A.CHANGE_DATE AS CHANGE_DATE , DECODE (A.ITEM_FLAG, 'N', '일반', 'G', '기획') AS GUBUN , A.AGENT AGENT , A.CHANGE_TIME , A.KEP_DATE , A.KEP_TIME FROM PRMTITEM A WHERE A.ITEM_NO LIKE 'PP%'
AND A.ITEM_NO LIKE '%' || #{st_item_no} || '%'
AND A.MAKER_NAME LIKE '%' || #{st_maker_name} || '%'
AND (A.DESCRIPTION LIKE '%' || #{st_desc_spec} || '%' OR A.SPECIFICATION LIKE '%' || #{st_desc_spec} || '%')
AND DECODE(A.STATUS, 'S', '요청', 'C', '게시', 'B', '반려', 'R','게시', 'A','보관', 'D','삭제','V','추천') = #{st_status}
AND A.ITEM_FLAG = #{st_item_flag}
AND A.AGENT = #{st_agent_code}
AND A.CATEGORY_NO IN ((SELECT STD_CATEG_ID FROM ICOMBYCA WHERE COM_CODE = 'PRMTITEM' AND PID = #{st_categ_id}))
AND A.CATEGORY_NO = #{st_categ_id}
ORDER BY DECODE(A.KEP_DATE||A.KEP_TIME, NULL, A.CHANGE_DATE||A.CHANGE_TIME, A.KEP_DATE||A.KEP_TIME) DESC
